practices.starterCode:
server {
  listen 8080;
  location /api/ {
    # Add the upstream and headers.
  }
}

practices.solutionCode:
server {
  listen 8080;
  server_name localhost;
  location = /api { return 308 /api/; }
  location /api/ {
    proxy_pass http://127.0.0.1:3000/;
    proxy_set_header Host $host;
    proxy_set_header X-Forwarded-Proto $scheme;
    proxy_set_header X-Forwarded-For $remote_addr;
  }
}

practices.starterCode:
server {
  listen 8080;
  root /var/www/learning;
  # Add three routing locations.
}

practices.solutionCode:
server {
  listen 8080;
  server_name localhost;
  root /var/www/learning;
  index index.html;
  location /assets/ { try_files $uri =404; }
  location /api/ {
    proxy_pass http://127.0.0.1:3000;
    proxy_set_header Host $host;
    proxy_set_header X-Forwarded-Proto $scheme;
  }
  location / { try_files $uri $uri/ /index.html; }
}

# Place both directives inside the existing http context.
limit_req_zone $binary_remote_addr zone=login_limit:10m rate=5r/m;
server {
  listen 8080;
  server_name localhost;
  location = /login {
    limit_req zone=login_limit burst=2 nodelay;
    limit_req_status 429;
    proxy_pass http://127.0.0.1:3000;
  }
}
